 const sw1=make('SW1','switch',350,190),sw2=make('SW2','switch',850,190),sw3=make('SW3','switch',600,470),pc1=make('PC1','pc',600,750),pc2=make('PC2','pc',100,190),switches=[sw1,sw2,sw3],pcs=[pc1,pc2];
 for(const[i,d]of switches.entries()){d.config.features.stp={mode:'rapid-pvst',vlanPriorities:{10:[8192,16384,32768][i],99:[8192,16384,32768][i]}};for(const[id,name]of [[10,'USERS'],[99,'NATIVE']]as const)d.config.vlans[id]={id,name,active:true};for(const n of [23,24]){const p=d.config.interfaces[g(n)];Object.assign(p,{mode:'trunk',nativeVlan:99,allowedVlans:[10,99]});Object.assign(p.features,{nonegotiate:true,portfast:false,bpduguard:false,rootGuard:false,loopGuard:false});}}
 for(const n of [23,24])sw3.config.interfaces[g(n)].adminUp=false;
 for(const[i,pc]of pcs.entries()){const p=[sw3,sw1][i].config.interfaces[g(1)];Object.assign(p,{mode:'access',vlan:10,description:'TO_'+pc.config.hostname});p.features.portfast=true;Object.assign(pc.config.interfaces.GigabitEthernet0,{ip:`192.168.10.${i===0?10:20}`,mask:'255.255.255.0'});pc.config.interfaces.GigabitEthernet0.features.dhcp=false;pc.config.defaultGateway=undefined;}
 const devices=[...switches,...pcs];for(const d of devices)d.startupConfig=structuredClone(d.config);
 const setting=(n:number,property:Extract<Criterion,{kind:'interface'}>['property'],value:string|number|boolean):Criterion=>({kind:'interface',device:sw3.id,interface:g(n),property,value});
 const protection:Criterion={kind:'all',criteria:[23,24].flatMap(n=>[setting(n,'adminUp',true),setting(n,'loopGuard',true),setting(n,'rootGuard',false),setting(n,'bpduguard',false),setting(n,'portfast',false),setting(n,'mode','trunk'),setting(n,'nativeVlan',99),{kind:'trunk-allowed',device:sw3.id,interface:g(n),vlans:[10,99]}])};
