 const core=make('CORE1','switch',650,120),sw=make('SW1','switch',400,370),edge=make('EDGE1','switch',900,370),pcs=[make('PC1','pc',150,370),make('PC2','pc',1150,370),make('PC3','pc',400,650),make('PC4','pc',900,650)],switches=[core,sw,edge];
