 sw.config.interfaces[g(23)].adminUp=false;
 for(const[i,pc]of pcs.entries()){const d=i%2===0?sw:edge,n=i<2?1:2,vlan=i<2?10:20,p=d.config.interfaces[g(n)];Object.assign(p,{mode:'access',vlan,description:'TO_'+pc.config.hostname});p.features.portfast=true;Object.assign(pc.config.interfaces.GigabitEthernet0,{ip:`192.168.${vlan}.${i%2===0?10:20}`,mask:'255.255.255.0'});pc.config.interfaces.GigabitEthernet0.features.dhcp=false;pc.config.defaultGateway=undefined;}
