 const asw=make('ASW1','switch',400,260),dsw=make('DSW1','switch',900,260),rogue=make('ROGUE','switch',400,570),pcs=[make('PC1','pc',160,260),make('PC2','pc',1140,260),make('PC3','pc',700,570)];
