 const lab:CatalogLab={id:'lab-'+(globalThis.crypto?.randomUUID?.()??Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),catalogId:'portfast-and-bpdu-guard',name:'PortFast and BPDU Guard'+(mode==='completed'?' · Completed':''),devices,links:[link('uplink',asw,g(24),dsw,g(24)),link('pc1',asw,g(1),pcs[0],'GigabitEthernet0'),link('pc2',dsw,g(1),pcs[1],'GigabitEthernet0'),link('rogue',asw,g(3),rogue,g(1)),link('pc3',rogue,g(2),pcs[2],'GigabitEthernet0')],notes:[{id:'note-portfast',x:650,y:100,text:'Protect ASW1 Gi0/1 + Gi0/3\nROGUE Gi0/1 starts shut\nTrigger → inspect → remove cause → recover'}],lesson:{title:'PortFast and BPDU Guard',description:'Protect host-facing access ports without making the trusted inter-switch trunk an edge port. VLAN 10 and all PC addresses are ready; DSW1 is the trusted root. ROGUE Gi0/1 starts shut so you can configure protection safely.\n\nFirst configure ASW1 Gi0/1 and Gi0/3 as VLAN 10 access ports with PortFast and BPDU Guard, then enable them. Verify PC1 and PC2 can communicate across the normal Gi0/24 trunk. PortFast accelerates host forwarding and still participates in STP.\n\nNext enable ROGUE Gi0/1. Wait for its actual BPDU to err-disable ASW1 Gi0/3. Inspect show interfaces status err-disabled and show logging. Check that DSW1 remains root and PC1/PC2 still communicate; PC3 behind ROGUE must not reach them. The incident task stays earned after recovery.\n\nRemove the cause by shutting ROGUE Gi0/1. Then reset ASW1 Gi0/3 with shutdown followed by no shutdown, retaining both protective features. Resetting before removing the source causes another trip. A recovered port with its peer shut remains link-down, which is expected. Automatic recovery remains disabled. Repeat both PC tests, save device configurations and save or export the lab.',objectives:[
  {id:'edge-portfast',title:'Configure and enable both ASW1 edge access ports',description:'Gi0/1 and Gi0/3: static access VLAN 10, PortFast, no shutdown. Keep Gi0/24 a normal trunk.',criterion:{kind:'all',criteria:[...[1,3].flatMap(n=>[setting(asw,n,'mode','access'),setting(asw,n,'vlan',10),setting(asw,n,'portfast',true),setting(asw,n,'adminUp',true)]),setting(asw,24,'portfast',false),setting(asw,24,'mode','trunk')]}},
  {id:'edge-guard',title:'Enable BPDU Guard on the two edge ports only',description:'Use spanning-tree bpduguard enable on Gi0/1 and Gi0/3; leave it disabled on Gi0/24.',criterion:{kind:'all',criteria:[setting(asw,1,'bpduguard',true),setting(asw,3,'bpduguard',true),setting(asw,24,'bpduguard',false)]}},
  {id:'trusted-forwarding',title:'Verify legitimate forwarding and the trusted root',description:'PC1’s edge and the uplink must forward VLAN 10, with DSW1 elected as root.',criterion:{kind:'all',criteria:[{kind:'stp-forwarding',device:asw.id,interface:g(1),vlans:[10]},{kind:'stp-forwarding',device:asw.id,interface:g(24),vlans:[10]},{kind:'stp-root',device:asw.id,vlan:10,root:dsw.id},{kind:'stp-root',device:dsw.id,vlan:10,root:dsw.id}]}},
  {id:'guard-incident',title:'Trigger and observe BPDU Guard err-disable',description:'Enable ROGUE Gi0/1. An actual received BPDU must trip ASW1 Gi0/3; inspect the reason and logs.',criterion:trip},
  {id:'remove-source',title:'Remove the offending BPDU source',description:'After observing the incident, shut ROGUE Gi0/1. Protection on ASW1 stays enabled.',criterion:sourceRemoved},
  {id:'recover-port',title:'Recover ASW1 Gi0/3 safely and retain protection',description:'After removing the cause, shutdown / no shutdown. Link-down is expected while ROGUE is shut; err-disabled is not.',criterion:{kind:'all',criteria:[sourceRemoved,setting(asw,3,'adminUp',true),setting(asw,3,'errDisabled',false),setting(asw,3,'portfast',true),setting(asw,3,'bpduguard',true)]}},
  {id:'pc1-ping',title:'Verify PC1 reaches PC2',description:'192.168.10.10 → 192.168.10.20. Repeat during the incident and after recovery.',criterion:{kind:'echo',device:pcs[0].id,from:'192.168.10.20'},action:{kind:'ping',device:pcs[0].id,target:'192.168.10.20'}},
  {id:'pc2-ping',title:'Verify PC2 reaches PC1',description:'192.168.10.20 → 192.168.10.10. No router or default gateway is needed.',criterion:{kind:'echo',device:pcs[1].id,from:'192.168.10.10'},action:{kind:'ping',device:pcs[1].id,target:'192.168.10.10'}},
 ]}};
 const doc:LabDocument={format:'netsim-lab',version:1,seed:20261029,lab};
 if(mode==='practice')return parseDocument(JSON.stringify(doc));
