 const switches=[make('SW1','switch',350,150),make('SW2','switch',850,150),make('SW3','switch',600,390)],pcs=[make('PC1','pc',420,650),make('PC2','pc',1050,390),make('PC3','pc',780,650),make('PC4','pc',150,390)],[sw1,sw2,sw3]=switches;
 for(const sw of switches){sw.config.features.stp={mode:'pvst',vlanPriorities:{10:32768,20:32768}};for(const[id,name]of [[10,'USERS'],[20,'GUESTS'],[99,'NATIVE']]as const)sw.config.vlans[id]={id,name,active:true};for(const n of [23,24]){const port=sw.config.interfaces[`GigabitEthernet0/${n}`];Object.assign(port,{mode:'trunk',nativeVlan:99,allowedVlans:[10,20,99],adminUp:false});port.features.nonegotiate=true;port.features.portfast=false;}}
 const endpoints:[Device,Device,number,number,string][]=[[pcs[0],sw3,1,10,'192.168.10.11'],[pcs[1],sw2,1,10,'192.168.10.12'],[pcs[2],sw3,2,20,'192.168.20.11'],[pcs[3],sw1,1,20,'192.168.20.12']];
 for(const[pc,sw,n,vlan,address]of endpoints){const port=sw.config.interfaces[`GigabitEthernet0/${n}`];Object.assign(port,{mode:'access',vlan,description:'TO_'+pc.config.hostname});port.features.portfast=false;Object.assign(pc.config.interfaces.GigabitEthernet0,{ip:address,mask:'255.255.255.0'});pc.config.interfaces.GigabitEthernet0.features.dhcp=false;pc.config.defaultGateway=undefined;}
