 Object.assign(r.config.interfaces['GigabitEthernet0/0'],{ip:'192.0.2.2',mask:'255.255.255.252',adminUp:true,description:'TO_DSW1'});
 Object.assign(r.config.interfaces['GigabitEthernet0/1'],{ip:'203.0.113.1',mask:'255.255.255.0',adminUp:true,description:'TO_SRV1'});
