 dsw.config.staticRoutes=[{network:'203.0.113.0',prefix:24,nextHop:'192.0.2.3',ad:1}];r.config.staticRoutes=[{network:'192.168.10.0',prefix:24,nextHop:'192.0.2.1',ad:1}];
